/* ==========================================================================
   Content: explorers, voyages, key terms (codex), ranks, upgrades
   Correct quiz answer is always listed first; the UI shuffles them.
   ========================================================================== */
'use strict';

const TERMS = {
  /* ---- Ships ---- */
  caravel: { t: 'Caravel', cat: 'ship', d: 'A small, fast and nimble sailing ship developed by the Portuguese in the 1400s. Its shallow hull let it explore coastlines and river mouths, and its triangular lateen sails let it sail closer into the wind than older ships.', f: 'A caravel was only about 20–25 meters long—about as long as two school buses—yet it crossed oceans.' },
  carrack: { t: 'Carrack (Nau)', cat: 'ship', d: 'A larger, sturdier ship with square sails and tall “castles” at the front and back. Carracks carried more cargo, food and crew for long voyages.', f: 'The Santa María and Magellan’s flagship, the Trinidad, were carracks.' },
  lateen: { t: 'Lateen Sail', cat: 'ship', d: 'A triangular sail hung from a long, slanted pole. Borrowed from Arab and Mediterranean sailors, it let ships sail at an angle toward the wind by zig-zagging (tacking).', f: 'Square sails are best with the wind behind you; lateen sails are best for sailing across or against it.' },
  reef: { t: 'Reefing the Sails', cat: 'ship', d: 'Rolling up or tying off part of a sail to make it smaller in strong winds, so the mast and rigging do not break.', f: 'In this game, press SPACE (or the sail button) to reef your sails during storms.' },
  /* ---- Navigation ---- */
  astrolabe: { t: 'Mariner’s Astrolabe', cat: 'nav', d: 'A heavy brass ring with a rotating sighting arm. Sailors measured how high the sun or a star was above the horizon to work out their latitude.', f: 'It was made heavy on purpose so it would hang still on a rolling deck.' },
  quadrant: { t: 'Quadrant', cat: 'nav', d: 'A quarter-circle instrument with a plumb line. A navigator sighted the North Star along its edge and read the angle—that angle was nearly equal to the ship’s latitude.', f: 'South of the equator the North Star disappears, so sailors had to learn to use the sun instead.' },
  compass: { t: 'Magnetic Compass', cat: 'nav', d: 'A magnetized needle that always points north, letting sailors hold a steady course even when clouds hid the sun and stars.', f: 'The compass was invented in China and reached European sailors by the 1200s.' },
  compassrose: { t: 'Compass Rose', cat: 'nav', d: 'The star-shaped diagram on maps that shows directions: the cardinal directions (North, East, South, West) and the intermediate directions (Northeast, Southeast, Southwest, Northwest).', f: 'Northeast is exactly halfway between North and East. Try steering NE with two arrow keys at once!' },
  latitude: { t: 'Latitude', cat: 'nav', d: 'Imaginary lines running east–west around the globe that measure how far north or south you are from the Equator, from 0° to 90°.', f: 'Sailors in the 1400s could measure latitude fairly well using the sun and stars.' },
  longitude: { t: 'Longitude', cat: 'nav', d: 'Imaginary lines running from the North Pole to the South Pole that measure how far east or west you are, in degrees.', f: 'Nobody could measure longitude accurately at sea until accurate clocks (chronometers) were invented in the 1700s!' },
  deadreckoning: { t: 'Dead Reckoning', cat: 'nav', d: 'Estimating a ship’s position by using its speed, its compass direction, and how much time has passed since the last known position.', f: 'Columbus was an expert at dead reckoning—his estimates were often remarkably accurate.' },
  league: { t: 'League', cat: 'nav', d: 'A unit of distance used by sailors, about 3 nautical miles (roughly 5.5 km). Originally, about how far a person could walk in an hour.', f: 'Jules Verne’s “20,000 Leagues Under the Sea” uses this same unit.' },
  portolan: { t: 'Portolan Chart', cat: 'nav', d: 'A sea chart showing coastlines, harbors and capes, covered in crisscrossing “rhumb lines” that radiate from compass roses to help sailors pick a course.', f: 'Portolan charts were drawn on sheepskin (vellum) and were sometimes kept as state secrets.' },
  cartography: { t: 'Cartography', cat: 'nav', d: 'The science and art of making maps. Every returning expedition changed Europe’s maps of the world.', f: 'Portugal hid its newest maps; leaking one could be punished by death.' },
  hourglass: { t: 'Ship’s Hourglass', cat: 'nav', d: 'A half-hour sand glass turned by the ship’s boys day and night. It kept time for the watches and for dead reckoning.', f: 'Each time the glass was turned, a bell was rung—eight bells marked the end of a four-hour watch.' },
  /* ---- Winds & geography ---- */
  tradewinds: { t: 'Trade Winds', cat: 'wind', d: 'Steady winds that blow toward the Equator: from the northeast in the Northern Hemisphere and from the southeast in the Southern Hemisphere.', f: 'Columbus rode the northeast trade winds straight west across the Atlantic.' },
  westerlies: { t: 'Westerlies', cat: 'wind', d: 'Winds between about 30° and 60° latitude that blow from the west toward the east. Sailors used them to return to Europe and to reach southern Africa.', f: 'Columbus discovered he could go west with the trade winds and return east with the westerlies.' },
  roaringforties: { t: 'Roaring Forties', cat: 'wind', d: 'Very strong westerly winds found between 40° and 50° south latitude, with huge waves and few lands to block them.', f: 'Later sailors raced along the Roaring Forties to reach Asia and Australia.' },
  doldrums: { t: 'Doldrums', cat: 'wind', d: 'A belt of calm, hot, still air near the Equator where the winds often die completely. Ships could sit motionless for days or weeks.', f: 'Today, “in the doldrums” means feeling stuck or gloomy.' },
  monsoon: { t: 'Monsoon', cat: 'wind', d: 'Seasonal winds of the Indian Ocean that change direction: blowing from the southwest in summer and from the northeast in winter. Traders timed their voyages by them.', f: 'Indian Ocean sailors had used the monsoons for well over 1,000 years before the Portuguese arrived.' },
  voltadomar: { t: 'Volta do Mar', cat: 'wind', d: 'Portuguese for “turn of the sea”: sailing far out into the open ocean in a giant arc to find favorable winds, instead of hugging the coast against the wind.', f: 'Da Gama’s volta do mar kept his crew out of sight of land for about three months.' },
  equator: { t: 'Equator', cat: 'place', d: 'The line of 0° latitude that circles the middle of the Earth, dividing it into the Northern and Southern Hemispheres.', f: 'South of the Equator, the North Star sinks below the horizon—sailors had to navigate by new stars.' },
  tropics: { t: 'Tropics of Cancer & Capricorn', cat: 'place', d: 'Lines of latitude at about 23.5° north (Cancer) and 23.5° south (Capricorn). Between them lies the warm tropical zone where the sun can be directly overhead.', f: 'Watch the dotted lines on the sea as you sail across them!' },
  sargasso: { t: 'Sargasso Sea', cat: 'place', d: 'A region of the North Atlantic covered with floating golden seaweed called sargassum. It is the only “sea” with no coastline.', f: 'Columbus’s crew worried the seaweed would trap their ships—it didn’t.' },
  strait: { t: 'Strait', cat: 'place', d: 'A narrow waterway that connects two larger bodies of water, such as the Strait of Gibraltar (Atlantic–Mediterranean).', f: 'Explorers searched for a strait through the Americas for over a century.' },
  capeboj: { t: 'Cape Bojador', cat: 'place', d: 'A cape on the coast of West Africa that sailors feared for centuries. Legends said the sea beyond it boiled and no ship could return. Gil Eanes sailed past it in 1434 for Prince Henry.', f: 'The real dangers were shallow reefs, strong currents and winds blowing away from home.' },
  capegoodhope: { t: 'Cape of Good Hope', cat: 'place', d: 'A rocky headland near the southern tip of Africa. Dias called it the Cape of Storms; King John II renamed it the Cape of Good Hope because it gave hope of a sea route to India.', f: 'The actual southernmost point of Africa is nearby Cape Agulhas.' },
  oceansea: { t: 'The Ocean Sea', cat: 'place', d: 'What Europeans called the Atlantic in the 1400s: one great ocean (Mare Oceanum) thought to surround all the known lands.', f: 'Columbus’s official title was “Admiral of the Ocean Sea.”' },
  pacific: { t: 'Pacific Ocean', cat: 'place', d: 'The largest ocean on Earth, covering about one-third of the planet. Magellan named it “Mar Pacífico” (peaceful sea) because it was calm when he entered it.', f: 'The Pacific is larger than all of Earth’s land put together.' },
  strmagellan: { t: 'Strait of Magellan', cat: 'place', d: 'A 570 km (350 mile) twisting channel near the southern tip of South America that connects the Atlantic and Pacific Oceans.', f: 'It took Magellan’s fleet 38 days to sail through it.' },
  tierradelfuego: { t: 'Tierra del Fuego', cat: 'place', d: '“Land of Fire”: the islands south of the Strait of Magellan, named for the many campfires of the Selk’nam and Yaghan peoples that sailors saw at night.', f: 'The Yaghan people kept fires burning even in their canoes to stay warm.' },
  patagonia: { t: 'Patagonia', cat: 'place', d: 'The cold, windswept southern region of South America. Magellan’s men called the tall Tehuelche people “Patagones,” and stories of giants spread across Europe.', f: 'The Tehuelche were tall, but they were not giants—that was an exaggeration!' },
  plata: { t: 'Río de la Plata', cat: 'place', d: 'A huge, wide river mouth (estuary) between today’s Argentina and Uruguay. Magellan explored it hoping it was the passage west—but its water was fresh.', f: 'Its name means “River of Silver.”' },
  spiceislands: { t: 'Spice Islands (Moluccas)', cat: 'place', d: 'A group of islands in today’s Indonesia that were the world’s only source of cloves and nutmeg—spices worth more than their weight in gold in Europe.', f: 'Reaching the Spice Islands by sailing west was the whole goal of Magellan’s voyage.' },
  indies: { t: 'The Indies', cat: 'place', d: 'Europeans’ name for India, China, Southeast Asia and the spice islands. Columbus called the islands he reached “the Indies”—which is why the Caribbean islands are still called the West Indies.', f: 'Columbus called the people he met “Indians” because he believed he was in Asia.' },
  cathay: { t: 'Cathay & Cipangu', cat: 'place', d: 'Marco Polo’s names for China (Cathay) and Japan (Cipangu). Columbus hoped to reach them and carried a letter for the Great Khan.', f: 'Marco Polo claimed Cipangu had palaces roofed with gold—Columbus wanted to find them.' },
  goldcoast: { t: 'Gold Coast', cat: 'place', d: 'The coast of West Africa (today’s Ghana) where Portugal traded for gold. In 1482 the Portuguese built the fortress of São Jorge da Mina (Elmina) there.', f: 'Elmina Castle still stands today and is a UNESCO World Heritage Site.' },
  swahili: { t: 'Swahili Coast', cat: 'place', d: 'The East African coast of wealthy trading city-states—like Kilwa, Mombasa and Malindi—linked by monsoon trade to Arabia, Persia, India and China.', f: 'Swahili, a language mixing Bantu and Arabic, is still spoken by over 100 million people.' },
  calicut: { t: 'Calicut', cat: 'place', d: 'A rich port city on India’s southwest (Malabar) coast, a center of the pepper and spice trade, ruled by the Zamorin. Da Gama arrived in May 1498.', f: 'Today it is called Kozhikode, in the Indian state of Kerala.' },
  sansalvador: { t: 'San Salvador (Guanahani)', cat: 'place', d: 'An island in the Bahamas where Columbus first landed on October 12, 1492. The Taíno people called it Guanahani.', f: 'Historians still debate exactly which Bahamian island was Columbus’s first landfall.' },
  hispaniola: { t: 'Hispaniola', cat: 'place', d: 'The Caribbean island shared today by Haiti and the Dominican Republic. Columbus built La Navidad there in 1492.', f: 'Columbus named it “La Isla Española”—“the Spanish Island.”' },
  philippines: { t: 'The Philippines', cat: 'place', d: 'A country of more than 7,000 islands in Southeast Asia. Magellan arrived in 1521; the islands were later named after Prince Philip of Spain.', f: 'Magellan’s arrival is remembered very differently in the Philippines—where Lapu-Lapu is a national hero.' },
  guam: { t: 'Guam', cat: 'place', d: 'An island in the western Pacific, home of the Chamorro people, where Magellan’s starving crew first found food after crossing the Pacific.', f: 'The Chamorro sailed fast outrigger canoes that amazed the Spanish.' },
  brazil: { t: 'Brazil', cat: 'place', d: 'A huge land in South America claimed for Portugal by Pedro Álvares Cabral in 1500, because it lay on Portugal’s side of the Tordesillas line.', f: 'It was named after brazilwood, a tree used to make red dye.' },
  newworld: { t: 'The New World', cat: 'idea', d: 'Europe’s name for the Americas once people realized these were continents unknown to them. In 1507 a mapmaker named them “America” after the explorer Amerigo Vespucci.', f: 'For the millions of people already living there, it was not new at all.' },
  /* ---- People ---- */
  henry: { t: 'Prince Henry the Navigator', cat: 'people', d: 'A Portuguese prince (1394–1460) who sponsored voyages down the coast of Africa and supported mapmakers, shipbuilders and navigators.', f: 'Despite his nickname, Henry hardly ever went to sea himself!' },
  john2: { t: 'King John II of Portugal', cat: 'people', d: 'Called “the Perfect Prince,” he sent Diogo Cão and Bartolomeu Dias south along Africa—and turned down Christopher Columbus’s plan to sail west.', f: 'He renamed Dias’s “Cape of Storms” the “Cape of Good Hope.”' },
  manuel: { t: 'King Manuel I of Portugal', cat: 'people', d: 'Known as “the Fortunate,” he sent Vasco da Gama to India in 1497. Spice profits made Portugal one of the richest kingdoms in Europe.', f: 'Manuel also refused to support Magellan—who then went to Spain.' },
  ferdisa: { t: 'Ferdinand & Isabella', cat: 'people', d: 'The “Catholic Monarchs” who ruled Spain and agreed in 1492 to sponsor Columbus, after he had asked them for years.', f: 'Columbus was famously turned down by Portugal, England and France before Spain said yes.' },
  charles: { t: 'King Charles I of Spain', cat: 'people', d: 'The young king (also Holy Roman Emperor Charles V) who sponsored Magellan’s expedition in 1518.', f: 'He was only 18 years old when he agreed to back Magellan.' },
  zamorin: { t: 'The Zamorin', cat: 'people', d: 'The Hindu ruler of Calicut. He was unimpressed by da Gama’s simple gifts of cloth, hats and honey—traders there were used to gold and silver.', f: '“Zamorin” comes from a title meaning “Lord of the Sea.”' },
  taino: { t: 'The Taíno', cat: 'people', d: 'The Indigenous people of the Caribbean islands who greeted Columbus. Within a few decades, disease, forced labor and violence caused their population to collapse.', f: 'Taíno words like hammock, canoe, hurricane and barbecue are still used in English today.' },
  khoikhoi: { t: 'The Khoikhoi', cat: 'people', d: 'Herding peoples of southern Africa who met Dias and da Gama. They raised cattle and sheep and traded them with the Portuguese.', f: 'At Mossel Bay in 1497, Khoikhoi musicians played flutes while Portuguese sailors danced.' },
  lapulapu: { t: 'Lapu-Lapu', cat: 'people', d: 'The chief of Mactan who refused to submit to Spain. His warriors defeated Magellan’s force at the Battle of Mactan on April 27, 1521.', f: 'Lapu-Lapu is honored as the first Filipino hero to resist foreign rule.' },
  elcano: { t: 'Juan Sebastián Elcano', cat: 'people', d: 'A Basque navigator who took command after Magellan’s death and brought the Victoria home in 1522, completing the first circumnavigation.', f: 'His coat of arms shows a globe with the words “Primus circumdedisti me”—“You were the first to go around me.”' },
  pinzon: { t: 'The Pinzón Brothers', cat: 'people', d: 'Martín Alonso and Vicente Yáñez Pinzón, experienced sailors from Palos who captained the Pinta and the Niña on Columbus’s first voyage.', f: 'Without the Pinzóns, Columbus might never have found enough sailors willing to go.' },
  pilot: { t: 'The Malindi Pilot', cat: 'people', d: 'An expert Indian Ocean navigator hired at Malindi who guided da Gama across the Arabian Sea to Calicut using the monsoon winds.', f: 'He is often said to be the famous navigator Ahmad ibn Mājid, but historians still debate it.' },
  pigafetta: { t: 'Antonio Pigafetta', cat: 'people', d: 'An Italian scholar who sailed with Magellan and kept a detailed journal. He was one of only 18 men to return on the Victoria.', f: 'Almost everything we know about the voyage comes from his journal.' },
  diogocao: { t: 'Diogo Cão', cat: 'people', d: 'A Portuguese explorer who reached the mouth of the Congo River in 1482 and Cape Cross (Namibia) in 1486, planting stone padrões and preparing the way for Dias.', f: 'One of his original padrões was taken to Germany in 1893; a replica stands at Cape Cross today.' },
  /* ---- Big ideas ---- */
  spicetrade: { t: 'The Spice Trade', cat: 'idea', d: 'Pepper, cinnamon, cloves and nutmeg grew in Asia and were worth a fortune in Europe, where they flavored and preserved food. Merchants from Venice and the Middle East controlled the routes—so Portugal and Spain wanted a direct sea route.', f: 'Pepper was so valuable it was sometimes called “black gold.”' },
  ggg: { t: 'God, Gold & Glory', cat: 'idea', d: 'The three main motives for European exploration: to spread Christianity (God), to gain wealth (Gold), and to win fame and power for themselves and their nations (Glory).', f: 'When asked why he came to India, one of da Gama’s men answered: “Christians and spices!”' },
  constantinople: { t: 'Fall of Constantinople (1453)', cat: 'idea', d: 'The Ottoman Turks conquered Constantinople in 1453. They now controlled key land routes to Asia, making overland trade harder and pricier—one reason Europeans looked to the sea.', f: 'Today the city is called Istanbul, in Türkiye.' },
  padrao: { t: 'Padrão', cat: 'idea', d: 'A stone pillar topped with a cross and the Portuguese coat of arms. Explorers placed them along the African coast to claim land and mark how far they had sailed.', f: 'Ships carried the heavy stone padrões all the way from Portugal!' },
  tordesillas: { t: 'Treaty of Tordesillas (1494)', cat: 'idea', d: 'An agreement that divided newly found lands between Spain and Portugal using a line about 370 leagues west of the Cape Verde Islands: lands to the west for Spain, to the east for Portugal.', f: 'This is why people in Brazil speak Portuguese, while most of South America speaks Spanish.' },
  circumnavigation: { t: 'Circumnavigation', cat: 'idea', d: 'Sailing all the way around the world. The first was completed by Magellan’s expedition, led home by Elcano, from 1519 to 1522.', f: 'Only 18 of about 270 men completed the first circumnavigation.' },
  columbianexchange: { t: 'The Columbian Exchange', cat: 'idea', d: 'The transfer of plants, animals, people and diseases between the Americas and Europe, Africa and Asia after 1492. Horses and wheat went west; corn, potatoes, tomatoes and chocolate went east. Diseases like smallpox devastated Indigenous peoples.', f: 'Before 1492 there were no tomatoes in Italy and no potatoes in Ireland!' },
  scurvy: { t: 'Scurvy', cat: 'idea', d: 'A disease caused by lack of vitamin C (found in fresh fruit and vegetables). Gums swell, teeth loosen and old wounds reopen. It killed more sailors than storms and battles combined.', f: 'Watch your crew’s health bar on long ocean crossings—landfall cures scurvy.' },
  mutiny: { t: 'Mutiny', cat: 'idea', d: 'When a ship’s crew rebels against its captain. Columbus, Dias and Magellan all faced angry crews who wanted to turn back.', f: 'Keep your crew’s morale up in this game—or they may mutiny!' },
  feitoria: { t: 'Feitoria (Trading Post)', cat: 'idea', d: 'A fortified trading station set up in a foreign land, where merchants stored goods and traded with local people.', f: 'Portugal built a chain of feitorias from Africa to India to Japan.' },
  colony: { t: 'Colony', cat: 'idea', d: 'A settlement in a distant land controlled by another country. La Navidad, built from the wrecked Santa María, was Spain’s first attempt at a settlement in the Americas.', f: 'When Columbus returned a year later, La Navidad had been destroyed.' },
  datel: { t: 'The Lost Day', cat: 'idea', d: 'When the Victoria reached the Cape Verde Islands in 1522, the crew found their logbook was one day behind. Sailing west all the way around the world, they had seen one fewer sunrise. This is why we have an International Date Line.', f: 'Pigafetta had written in his journal every single day—so they knew it was no mistake.' },
  sailorslife: { t: 'Life at Sea', cat: 'idea', d: 'Sailors ate hardtack (hard ship’s biscuit), salted meat and fish, and drank wine and water that often turned foul. Most slept on the open deck. Ship’s boys did the hardest chores.', f: 'Rats, cockroaches and lice were constant shipmates.' },
  terraincognita: { t: 'Terra Incognita', cat: 'idea', d: 'Latin for “unknown land.” Mapmakers wrote it across regions they knew nothing about.', f: 'Old maps based on Ptolemy showed an unknown southern land enclosing the Indian Ocean—Dias proved it wrong.' },
  ptolemy: { t: 'Ptolemy’s Geography', cat: 'idea', d: 'A book of maps by Claudius Ptolemy, a Greek-Egyptian scholar of the 2nd century. Rediscovered in 1400s Europe, it stretched Asia too far east and showed the Indian Ocean as a closed lake.', f: 'The map on this game’s main screen is based on how Europeans pictured the world around 1490.' },
  earthsize: { t: 'The Size of the Earth', cat: 'idea', d: 'Educated Europeans knew the Earth was round. But Columbus calculated it about 25% too small and Asia far too wide, so he thought Japan was only about 2,400 miles west of the Canary Islands. The real distance is over 10,000 miles!', f: 'Columbus was wrong—but the Americas happened to lie right where he expected Asia.' },
  ageofexploration: { t: 'Age of Exploration', cat: 'idea', d: 'The period from the 1400s to the 1600s when European sailors searched for new trade routes, mapped much of the world and connected the continents—with huge consequences, both good and terrible.', f: 'It is also called the Age of Discovery—though the lands “discovered” were already home to millions.' },
};

